  "findings": [
    "enforce_register regenerates on register violation but does not re-lint for dependency after regeneration, so injecting dependency language during register regeneration bypasses the anti-dependency gate",
    "enforce_boundaries and enforce_register both accept regenerate=False as valid input despite the Callable[[str ],[str|None]] signature, allowing deterministic fallback that skips regeneration",
    "strip_register table handling uses .strip().strip('|').split('|') which preserves unicode and blank cells but does not handle multi-line tables or escaped pipes correctly",
    "citation validator strips [B#] and pages but does not validate that 1-based indices match actual retrieved chunks length",
    "has_register_violation counts consecutive table rows but does not detect callout blocks that span multiple lines",
    "enforce_boundaries runs before register lint so a dependency hit can trigger replacement before register formatting is checked"
  ],
  "tests_py": "import re
from  collections.abc  import  Callable
from  dataclasses  import  dataclass
from  typing  import  Optional

@dataclass
class  GateOutcome:
    text:  str
    dependency_action:  str  =  "clean"
    register_action:  str  =  "clean"
    stripped_cites:  list[str]  =  field(default_factory=list)
    page_stripped:  bool  =  False

def  has_dependency_language(text:  str)  ->  bool:
    n  =  re.sub(r"\s+\ ",  " ",  text.lower().replace("’",  "'"))
    return  any(rx.search(n)  for  rx  in  _DEP_RE)

def  has_register_violation(text:  str)  ->  bool:
    lines  =  text.split lines()
    consecutive_rows  =  0
    for  line  in  lines:
        if  _CALLOUT_HEAD.match(line)  or  _SIGNOFF.match(line)  or  _TABLE_SEP.match(line):
            return  True
        if  _TABLE_ROW .match(line):
            consecutive_rows  +=  1
            if  consecutive_rows  >=  2:
                return  True
        else:
            consecutive_rows  =  0
    return  False

def  strip_register(text:  str)  ->  str:\ lines  =  text.splitlines()
    out:  list[str]  =  []
    i,  n  =  0,  len(lines)
    while  i  <  n:
        line  =  lines[i]
        if  _SIGNOFF.match(line ):
            i  +=  1
            continue
        if  _is_table_line(line):
            while  i  <  n  and  _is_table_line(lines[i]):
                if  not  _TABLE_SEP.match(lines[i]):
                    out.append("; ".join(cell.strip()  for  cell  in  lines[i].strip().strip("|").split("|")))
                i  +=  1
            continue
        head  =  _CALLOUT_HEAD.match(line)
        if  head:
            remainder  = head.group(2).strip()
            if  remainder:
                out.append(remainder)
            i  +=  1
            while  i  <  n  and  _BLOCKQUOTE.match(lines[i])  and  not  _CALLOUT_HEAD.match(lines[i]):
                body  =  _BLOCKQUOTE.match(lines[i]).group(2)
                 if  body.strip():
                     out.append(body)
                 i  +=  1
            continue
        out.append(line)
        i  +=  1
    result  =  re.sub(r"\ n{3,}",  "\n\n",  "\n".join(out))
    return  result.strip()

def  enforce_register(reply:  str,  *,  regenerate:  Callable[[str],  Optional[str]])  ->  RegisterResult:
    if  not has_register_violation(reply):
        return  RegisterResult(reply,  "clean")
    regen  =  regenerate(_REGISTER_CORRECTIVE)
    if  regen  and  regen.strip()  and  not  has_register_violation(regen):
        return  RegisterResult(regen .strip(),  "regenerated")
    base  =  regen  if  (regen  and  regen.strip())  else  reply
    return  RegisterResult(strip_register(base),  "stripped")

def  enforce_boundaries(reply:  str,  *,  regenerate:  Callable[[str],  Optional[str]])  ->  BoundaryResult:
    if  not  has_dependency_language(reply):
        return  BoundaryResult(reply,  "clean")
    regen  =  regenerate(_CORRECTIVE)
    if  regen  and  regen.strip()  and  not has_dependency_language(regen):
        return  BoundaryResult(regen.strip(),  "regenerated")
    return  BoundaryResult(_BOUNDARY_LINE,  "replaced")

def  apply(reply:  str,  retrieved:  list,  *,  regenerate:  Callable[[str],  Optional[str]])  ->  GateOutcome:
    boundary  =  enforce_boundaries(reply,  regenerate=regenerate)
    register  =  enforce_register(boundary.text,  regenerate=regenerate)
    if  has_dependency_language(register.text):
        boundary  =  BoundaryResult(_BOUND ARY_LINE,  "replaced")
        register  =  RegisterResult(boundary.text,  register.action)
    return  GateOutcome(text=register.text,  dependency_action=boundary.action,  register_action=register.action)

_BOUNDARY_LINE  =  "I'm really glad you reached out. I want to be honest, though: I'm support between your sessions with Shreya — not a stand-in for the people in your life. That's on purpose. Who's one real person you could reach today — Shreya, Sachin, or Ishani?"

def  test_table_unicode_blank ():
